            return null;
        }
        try {
            byte[] expectedSignature = sign(segments[0] + "." + segments[1]);
            byte[] providedSignature = Base64.getUrlDecoder().decode(segments[2]);
            if (!MessageDigest.isEqual(expectedSignature, providedSignature)) {
                log.debug("Rejected token with invalid signature");
