import com.dbconsole.platform.entity.Instance;
import com.dbconsole.platform.entity.InstanceGroup;
import com.dbconsole.platform.entity.User;
import com.dbconsole.platform.mapper.InstanceGroupMapper;
import com.dbconsole.platform.mapper.InstanceMapper;
import com.dbconsole.platform.mapper.UserMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.CommandLineRunner;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Component;

import java.time.LocalDateTime;
import java.util.List;

/**
 * Seeds the baseline data of the console once the datasource and the retained
 * {@code schema.sql} initialization have run.
 *
 * <p>Each block is guarded by an emptiness check (row count zero) on its own table, so restarting
 * the application never duplicates rows.</p>
 */
@Component
public class DataInitializer implements CommandLineRunner {

    private static final Logger log = LoggerFactory.getLogger(DataInitializer.class);

    private static final String ROLE_ADMIN = "ADMIN";
    private static final String ROLE_USER = "USER";

    private final UserMapper userMapper;
    private final InstanceGroupMapper instanceGroupMapper;
    private final InstanceMapper instanceMapper;
    private final PasswordEncoder passwordEncoder;

    public DataInitializer(UserMapper userMapper,
                           InstanceGroupMapper instanceGroupMapper,
                           InstanceMapper instanceMapper,
                           PasswordEncoder passwordEncoder) {
        this.userMapper = userMapper;
        this.instanceGroupMapper = instanceGroupMapper;
        this.instanceMapper = instanceMapper;
        this.passwordEncoder = passwordEncoder;
    }

    @Override
    public void run(String... args) {
        seedUsers();
        seedGroups();
        seedInstances();
    }

    /**
     * Creates the baseline accounts when the {@code users} table is empty.
     */
    private void seedUsers() {
        if (userMapper.countAll() > 0) {
            return;
        }
        LocalDateTime now = LocalDateTime.now();
        insertUser("admin", "admin123", ROLE_ADMIN, now);
        insertUser("user1", "user123", ROLE_USER, now);
        insertUser("user2", "user123", ROLE_USER, now);
        log.info("Seeded baseline users");
    }

    private void insertUser(String username, String rawPassword, String role, LocalDateTime createdAt) {
        User user = new User();
        user.setUsername(username);
        user.setPassword(passwordEncoder.encode(rawPassword));
        user.setRole(role);
        user.setCreatedAt(createdAt);
        userMapper.insert(user);
    }

    /**
     * Creates the baseline groups when the {@code instance_groups} table is empty.
     */
    private void seedGroups() {
        if (instanceGroupMapper.countAll() > 0) {
            return;
        }
        LocalDateTime now = LocalDateTime.now();
        User admin = userMapper.findByUsername("admin");
        User user1 = userMapper.findByUsername("user1");
        if (admin != null) {
            insertGroup("默认分组", "默认实例分组", admin.getId(), now);
        }
        if (user1 != null) {
            insertGroup("测试环境", "测试环境实例", user1.getId(), now);
        }
        log.info("Seeded baseline instance groups");
    }

    private void insertGroup(String name, String description, Long ownerId, LocalDateTime createdAt) {
        InstanceGroup group = new InstanceGroup();
        group.setName(name);
        group.setDescription(description);
        group.setOwnerId(ownerId);
        group.setCreatedAt(createdAt);
        instanceGroupMapper.insert(group);
    }

    /**
     * Creates the baseline instance when the {@code instances} table is empty; it is attached to
     * the first existing group and owned by {@code user1}.
     */
    private void seedInstances() {
        if (instanceMapper.countAll() > 0) {
            return;
        }
        User user1 = userMapper.findByUsername("user1");
        if (user1 == null) {
            log.warn("Skipped instance seeding: owner account 'user1' is missing");
            return;
        }
        List<InstanceGroup> groups = instanceGroupMapper.findAll();
        Long groupId = groups.isEmpty() ? null : groups.get(0).getId();

        LocalDateTime now = LocalDateTime.now();
        Instance instance = new Instance();
        instance.setName("内部MySQL");
        instance.setDbType("MYSQL");
        instance.setHost("mysql.internal.com");
        instance.setPort(3306);
        instance.setSchemaName("app_db");
        instance.setAccount("root");
        instance.setStatus("CREATED");
        instance.setGroupId(groupId);
        instance.setOwnerId(user1.getId());
        instance.setCreatedAt(now);
        instance.setUpdatedAt(now);
        instanceMapper.insert(instance);
        log.info("Seeded baseline instance");
    }
}
