  "content": "import com.dbconsole.platform.security.JwtTokenProvider;

/** Standalone probe of JwtTokenProvider semantics (verification only, not project code). */
public class JwtProbe {

    public static void main(String[] args) throws Exception {
        JwtTokenProvider provider = new JwtTokenProvider("dbconsole-secret-key-for-jwt-token-2024", 7200);
        String token = ***"user1", "USER");
        System.out.println("issued            -> " + provider.getUsernameFromToken(token));
        System.out.println("role              -> " + provider.getRoleFromToken(token));
        System.out.println("validate          -> " + provider.validateToken(token));

        String[] parts = token.split("\\.");
        System.out.println("tampered payload  -> " + provider.getUsernameFromToken(parts[0] + "." + parts[1] + "x." + parts[2]));
        System.out.println("tampered signature-> " + provider.getUsernameFromToken(parts[0] + "." + parts[1] + "." + "AAAA"));
        System.out.println("malformed         -> " + provider.getUsernameFromToken("nonsense"));
        System.out.println("null              -> " + provider.getUsernameFromToken(null));
        System.out.println("empty             -> " + provider.getUsernameFromToken(""));

        // other secret must not verify
        JwtTokenProvider other = new JwtTokenProvider("another-secret", 7200);
        System.out.println("foreign secret    -> " + other.getUsernameFromToken(token));
        System.out.println("foreign validates -> " + other.validateToken(other.generateToken("user1", "USER")));

        // already expired token
        JwtTokenProvider expired = new JwtTokenProvider("dbconsole-secret-key-for-jwt-token-2024", -10);
        String dead = expired.generateToken("user1", "USER");
        System.out.println("expired username  -> " + expired.getUsernameFromToken(dead));
        System.out.println("expired validate  -> " + expired.validateToken(dead));

        // short secret *** (fewer than 32 bytes)
        JwtTokenProvider shortSecret = new JwtTokenProvider("s3cr3t", 60);
        String shortToken = ***"admin", "ADMIN");
        System.out.println("short secret      -> " + shortSecret.getUsernameFromToken(shortToken));
    }
}
"
}

